import stylesText from './local-ai-switch.css?inline';
import { cssStyleSheet } from '../../../utils/css.js';
import { createComponentLogger } from '../../../utils/component-logger.js';
import { AiService } from '../../../services/ai.service.js';
import { localAiLabel } from '../local-ai-label.js';
import type { LocalAiMode, LocalAiState } from '@motivation/shared';

const styles = cssStyleSheet(stylesText);
const log = createComponentLogger('ai/local-ai-switch');

/** Story 426: the laptop reaches the chat server's loopback port through this tunnel. */
export const LOCAL_AI_TUNNEL_COMMAND = 'ssh -N -L 8080:localhost:11438 ties@192.168.178.170';
const TICK_MS = 15_000;

const template = document.createElement('template');
template.innerHTML = `
    <label class="row"><input type="checkbox" id="on" disabled> Local AI</label>
    <p class="status" id="status">Loading...</p>
    <label class="row" id="keep-row" hidden><input type="checkbox" id="keep"> Keep on</label>
    <div class="tunnel" id="tunnel" hidden>
        <p>From the laptop:</p>
        <code id="command"></code>
        <p>then open <code>http://localhost:8080</code>, or point a harness at <code>/v1/chat/completions</code> or <code>/v1/messages</code>.</p>
    </div>
    <pre class="error" id="error" hidden></pre>
`;

/**
 * Story 426: holds the chat server up (30 minutes, or kept on) with its web UI reachable over an
 * SSH tunnel. Starting can take a while — the server pauses Immich and loads the model — so the
 * switch stays disabled until the server answers.
 */
export class LocalAiSwitch extends HTMLElement {
    private state: LocalAiState | null = null;
    private ticker: ReturnType<typeof setInterval> | null = null;

    constructor() {
        super();
        this.attachShadow({ mode: 'open' });
        this.shadowRoot!.adoptedStyleSheets = [styles];
        this.shadowRoot!.appendChild(template.content.cloneNode(true));
        this.$('command').textContent = LOCAL_AI_TUNNEL_COMMAND;
        this.input('on').addEventListener('change', () => void this.set(this.input('on').checked ? 'timed' : 'off'));
        this.input('keep').addEventListener('change', () => void this.set(this.input('keep').checked ? 'kept' : 'timed'));
    }

    connectedCallback() {
        void this.load();
        this.ticker = setInterval(() => this.tick(), TICK_MS);
    }

    disconnectedCallback() {
        if (this.ticker) clearInterval(this.ticker);
        this.ticker = null;
    }

    private $(id: string): HTMLElement {
        return this.shadowRoot!.getElementById(id)!;
    }

    private input(id: 'on' | 'keep'): HTMLInputElement {
        return this.$(id) as HTMLInputElement;
    }

    private async load(): Promise<void> {
        try {
            this.render(await AiService.getLocalAi());
        } catch (err) {
            this.fail('Failed to read the Local AI switch', err);
        }
    }

    private async set(mode: LocalAiMode): Promise<void> {
        this.input('on').disabled = true;
        this.input('keep').disabled = true;
        this.$('status').textContent = mode === 'off' ? 'Turning off...' : 'Starting the chat server...';
        this.$('error').hidden = true;
        try {
            this.render(await AiService.setLocalAi(mode));
        } catch (err) {
            // A failed start leaves the switch off on the server: show what it is now, then why.
            await this.load();
            this.fail('Failed to switch Local AI', err);
        }
    }

    /** Re-label the time left; once a timed hold has run out, read the server's state again. */
    private tick(): void {
        if (!this.state || this.state.mode !== 'timed') return;
        if (localAiLabel(this.state, Temporal.Now.instant()) === 'Off') {
            void this.load();
            return;
        }
        this.render(this.state);
    }

    private render(state: LocalAiState): void {
        this.state = state;
        const on = state.mode !== 'off';
        this.input('on').disabled = false;
        this.input('on').checked = on;
        this.input('keep').disabled = false;
        this.input('keep').checked = state.mode === 'kept';
        this.$('keep-row').hidden = !on;
        this.$('tunnel').hidden = !on;
        this.$('status').textContent = localAiLabel(state, Temporal.Now.instant());
    }

    private fail(message: string, err: unknown): void {
        log.error(message, err);
        const error = this.$('error');
        error.hidden = false;
        error.textContent = err instanceof Error ? err.message : String(err);
    }
}

if (!customElements.get('local-ai-switch')) {
    customElements.define('local-ai-switch', LocalAiSwitch);
}
